{"type": "update", "filePath": "/Users/dhruva/src/dhruvasagar/rails-upgrade-with-claude/app/models/order.rb", "content": "class Order < ApplicationRecord
  belongs_to :user
  has_many :order_items, dependent: :destroy
  has_many :products, through: :order_items

  STATUSES = %w[pending processing shipped delivered cancelled refunded].freeze

  validates :status, presence: true, inclusion: { in: STATUSES }
  validates :total_amount, presence: true, numericality: { greater_than_or_equal_to: 0 }

  scope :recent, -> { order(created_at: :desc) }
  scope :completed, -> { where(status: "delivered") }
  scope :pending, -> { where(status: "pending") }
  scope :for_user, ->(user) { where(user: user) }

  before_validation :calculate_total, on: :create
  after_create :send_confirmation

  def calculate_total
    self.total_amount = order_items.sum { |item| item.quantity * item.unit_price }
  end

  def cancel!
    return false unless status.in?(%w[pending processing])

    update(status: "cancelled")
    order_items.each { |item| item.product.restore_stock!(item.quantity) }
  end

  def fulfillable?
    status == "processing" &&
      order_items.all? { |item| item.product.stock_quantity >= item.quantity }
  end

  private

  def send_confirmation
    SendOrderConfirmationJob.perform_later(id)
  end
end
